/** Async Action */
export const AsyncAction: Story = {
  name: 'Async Action',
  tags: ['example-async-action'],
  render: () => AsyncActionExample,
  parameters: {
    docs: {
      source: { language: 'html', code: '<script setup lang="ts">\nimport { ref } from \'vue\';\nimport { PixelAlertDialog } from \'@pxlkit/ui-kit-vue\';\n\nconst open = ref(false);\nconst error = ref<string | null>(null);\n\nfunction show() {\n  error.value = null;\n  open.value = true;\n}\n\nconst submit = () => new Promise<void>((resolve) => setTimeout(resolve, 600));\n</script>\n\n<template>\n  <div>\n    <button type="button" @click="show">Submit</button>\n    <PixelAlertDialog\n      v-model:open="open"\n      title="Submit report?"\n      :description="error ?? \'The report will be sent for review.\'"\n      action-label="Submit"\n      @action="submit"\n      @error="(e) => (error = e instanceof Error ? e.message : \'Failed\')"\n    />\n  </div>\n</template>' },
    },
  },
};
